import sys
from itertools import combinations
from math import sqrt

def distance(p1, p2):
    return sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def can_slice(fruit1, fruit2, other_fruits):
    x1, y1 = fruit1
    x2, y2 = fruit2
    if x1 == x2:
        # Vertical line
        for fx, fy in other_fruits:
            if abs(fx - x1) <= 1:
                return True
        return False
    slope = (y2 - y1) / (x2 - x1)
    intercept = y1 - slope * x1
    for fx, fy in other_fruits:
        if abs(slope * fx - fy + intercept) / sqrt(1 + slope ** 2) <= 1:
            return True
    return False

def max_sliced_fruits(fruits):
    n = len(fruits)
    max_slices = 0
    for fruit1, fruit2 in combinations(fruits, 2):
        other_fruits = [fruit for fruit in fruits if fruit != fruit1 and fruit != fruit2]
        if all(can_slice(fruit1, fruit2, other_fruits) for fruit in other_fruits):
            max_slices = max(max_slices, len(other_fruits) + 2)
    return max_slices

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    fruits = []
    index = 1
    for _ in range(n):
        x = float(data[index])
        y = float(data[index + 1])
        fruits.append((x, y))
        index += 2

    result = max_sliced_fruits(fruits)
    print(result)

if __name__ == "__main__":
    main()
